<?php
if(!isset($db)){http_response_code(404);exit;}
function growthSetup(){global $db;
$db->exec("CREATE TABLE IF NOT EXISTS onb_discount_fixed(code VARCHAR(32) PRIMARY KEY,amount DECIMAL(12,2) NOT NULL) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_discounts(code VARCHAR(32) PRIMARY KEY,percent INT NOT NULL,active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_discount_uses(booking_id INT PRIMARY KEY,code VARCHAR(32) NOT NULL,saved DECIMAL(12,2) NOT NULL) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_booking_agent_link(booking_id INT PRIMARY KEY,lead_id INT NOT NULL UNIQUE) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_vault(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,label VARCHAR(150) NOT NULL,nonce VARBINARY(24) NOT NULL,cipher MEDIUMBLOB NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
$db->exec("CREATE TABLE IF NOT EXISTS onb_reminder_log(booking_id INT NOT NULL,kind VARCHAR(20) NOT NULL,period VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,PRIMARY KEY(booking_id,kind,period)) ENGINE=InnoDB");
}
function growthKey(){global $c;$key=base64_decode($c['vault_key']??'',true);if(!function_exists('sodium_crypto_secretbox')||$key===false||strlen($key)!==32)throw new RuntimeException('Vault is not configured.');return $key;}
function growthAction($action,$u,$admin){if(!$u)throw new RuntimeException('Sign in required.');growthSetup();
if($action==='growth_discount'&&$admin){$code=strtoupper(p('code'));$fixed=p('discount_type')==='fixed';$rate=$fixed?1:filter_var(p('percent'),FILTER_VALIDATE_INT);if($fixed&&(!preg_match('/^\\d{1,9}(\\.\\d{1,2})?$/D',p('percent'))||(float)p('percent')<=0))throw new RuntimeException('Invalid CAD amount.');if(!preg_match('/^[A-Z0-9_-]{3,32}$/D',$code)||$rate===false||$rate<1||$rate>90)throw new RuntimeException('Invalid code or percentage.');global $db;$db->beginTransaction();try{q('INSERT INTO onb_discounts(code,percent,active) VALUES(?,?,?) ON DUPLICATE KEY UPDATE percent=VALUES(percent),active=VALUES(active)',[$code,$rate,isset($_POST['active'])?1:0]);if($fixed)q('INSERT INTO onb_discount_fixed VALUES(?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount)',[$code,p('percent')]);else q('DELETE FROM onb_discount_fixed WHERE code=?',[$code]);$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}}
elseif($action==='growth_upload'&&!$admin){$key=growthKey();$f=$_FILES['document']??[];if(($f['error']??1)!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']>5000000||$f['size']<5||!p('label')||strlen(p('label'))>150)throw new RuntimeException('Upload a PDF under 5 MB.');$data=file_get_contents($f['tmp_name']);if(substr($data,0,5)!=='%PDF-')throw new RuntimeException('PDF only.');$nonce=random_bytes(24);q('INSERT INTO onb_vault(user_id,label,nonce,cipher) VALUES(?,?,?,?)',[$u['id'],p('label'),$nonce,sodium_crypto_secretbox($data,$nonce,$key)]);}
elseif($action==='growth_delete'&&!$admin){q('DELETE FROM onb_vault WHERE id=? AND user_id=?',[(int)p('id'),$u['id']]);}
else throw new RuntimeException('Access denied.');go('page=growth');}
function growthDownload($u){if(!$u){http_response_code(403);exit;}growthSetup();$r=q('SELECT * FROM onb_vault WHERE id=? AND user_id=?',[(int)($_GET['id']??0),$u['id']])->fetch();if(!$r){http_response_code(404);exit;}try{$data=sodium_crypto_secretbox_open($r['cipher'],$r['nonce'],growthKey());}catch(Throwable $e){http_response_code(503);exit;}if($data===false){http_response_code(503);exit;}header('Cache-Control: no-store');header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="travel-document.pdf"');echo $data;exit;}
function growthView($u,$admin){if(!$u){echo '<p>Sign in required.</p>';return;}growthSetup();bookingSetup();agentSetup();?>
<div class="onb-dash"><div class="dash-hero"><h1><?=$admin?'Discounts & marketing analytics':'Private document vault'?></h1></div>
<?php if($admin):?><h2>Discount codes</h2><?php form('growth_discount');field('code','Code');echo '<label>Discount type<select name="discount_type"><option value="percent">Percentage (%)</option><option value="fixed">Fixed amount (CAD)</option></select></label>';field('percent','Discount value');?><label><input type="checkbox" name="active" checked> Active</label><button>Save code</button></form><?php foreach(q('SELECT d.*,COUNT(v.booking_id) AS uses,COALESCE(SUM(v.saved),0) AS saved FROM onb_discounts d LEFT JOIN onb_discount_uses v ON v.code=d.code GROUP BY d.code,d.percent,d.active') as $r):?><p><?=h($r['code'])?> · <?php $fixed=q('SELECT amount FROM onb_discount_fixed WHERE code=?',[$r['code']])->fetchColumn();echo $fixed!==false?'CAD '.chr(36).h($fixed):h($r['percent']).'%';?> · <?=$r['active']?'Active':'Disabled'?> · <?=$r['uses']?> quotations · CAD $<?=h($r['saved'])?> discounts</p><?php endforeach;?>
<h2>Marketing performance — last 30 days</h2><div class="metrics"><?php foreach(['Enquiries'=>"SELECT COUNT(*) FROM enquiries WHERE created_at>=NOW()-INTERVAL 30 DAY",'Agent leads'=>"SELECT COUNT(*) FROM onb_agent_leads WHERE created_at>=NOW()-INTERVAL 30 DAY",'Direct quotes'=>"SELECT COUNT(*) FROM onb_bookings WHERE agent_id IS NULL AND created_at>=NOW()-INTERVAL 30 DAY",'Agent quotes'=>"SELECT COUNT(*) FROM onb_bookings WHERE agent_id IS NOT NULL AND created_at>=NOW()-INTERVAL 30 DAY",'Confirmed or completed quotes'=>"SELECT COUNT(*) FROM onb_bookings WHERE stage IN ('confirmed','completed') AND created_at>=NOW()-INTERVAL 30 DAY"] as $label=>$sql):?><article><span><?=h($label)?></span><strong><?=h(q($sql)->fetchColumn())?></strong></article><?php endforeach;?></div><p>Counts are recorded activity, not unique visitors or advertising attribution.</p>
<?php else:?><p>Private PDFs only. Do not upload passports or identity documents until the privacy and retention arrangements are approved.</p><form method="post" enctype="multipart/form-data"><?=token()?><input type="hidden" name="action" value="growth_upload"><?php field('label','Document label');?><label>PDF<input type="file" name="document" accept="application/pdf" required></label><button>Upload privately</button></form><?php foreach(q('SELECT id,label,created_at FROM onb_vault WHERE user_id=?',[$u['id']]) as $r):?><article><?=h($r['label'])?> · <a href="?page=vault_download&amp;id=<?=$r['id']?>">Download</a><?php form('growth_delete');?><input type="hidden" name="id" value="<?=$r['id']?>"><button>Delete</button></form></article><?php endforeach;endif;?></div><?php }
function growthPolicies(){?>
<section class="policy-centre"><span class="eyebrow">OUR NEXT BOARDING / TRUST & TRANSPARENCY</span><h1>Policies & travel terms</h1><p>Understand how we handle your information and how travel arrangements are governed.</p><nav class="policy-links" aria-label="Policy sections"><a href="#privacy">Privacy policy</a><a href="#booking">Booking terms</a><a href="#cancellation">Cancellation & refunds</a><a href="#website">Website use</a></nav>
<article id="privacy"><h2>Privacy policy</h2><h3>Information we collect</h3><p>When you create an account, contact us or request a journey, we collect the information you provide, including your name, email, travel preferences, booking details and payment references. We also use session cookies, referral information and security logs to operate and protect the website.</p><h3>How we use information</h3><p>We use personal information to respond to enquiries, administer accounts, prepare quotations, coordinate travel arrangements, maintain financial records, prevent misuse and communicate important journey updates. Optional promotional emails are subject to your consent.</p><h3>Sharing and international travel</h3><p>Relevant information may be shared with travel suppliers and service providers when necessary to arrange requested services, or when required by law. International travel may involve processing information outside Canada, where different privacy laws apply.</p><h3>Security and retention</h3><p>We use account access controls and encrypted storage for the private document vault. No system can guarantee absolute security. Information is retained as needed for the stated purposes, contractual obligations and applicable legal requirements. Please do not upload passports or identity documents unless specifically authorized through an approved process.</p><h3>Your choices and rights</h3><p>You may manage marketing consent in your travel hub and contact us to request access, correction or deletion of personal information, subject to applicable law. Essential account and booking communications are separate from marketing. For privacy questions or complaints, use our <a href="?page=contact">contact form</a> and identify your request as a privacy matter.</p></article>
<article id="booking"><h2>General booking terms</h2><p>Submitting an enquiry does not create a confirmed reservation. Availability, prices, inclusions, payment deadlines and supplier conditions must be confirmed in writing before a booking commitment. Review the individual journey details and written quotation before accepting. Travellers are responsible for checking passport, visa, entry and insurance requirements applicable to their circumstances.</p></article>
<article id="cancellation"><h2>Cancellation & refund policy</h2><p>Cancellation and refund conditions differ by journey. There is no universal cancellation fee or refund schedule across Our Next Boarding.</p><p>Each journey's <strong>Before you go — Cancellation and refunds</strong> section sets out its applicable conditions when available. Review those conditions together with the written booking agreement before making payment. If conditions have not yet been published, request them in writing before committing.</p><p>Submit cancellation requests through our contact form, including your booking reference. Applicable deadlines, deposit treatment, supplier restrictions, fees and refund processing arrangements are determined by the agreed trip-specific terms and applicable law. If we cancel or materially change a journey, we will communicate the applicable options and remedies. Nothing in these policies limits mandatory consumer rights.</p><a class="btn" href="?page=trips">Explore journeys and their policies</a></article>
<article id="website"><h2>Website use</h2><p>Use the website lawfully, provide accurate information and keep account credentials confidential. Do not misuse referral codes, upload unlawful content or attempt unauthorized access. Website descriptions and availability may change; confirmed written booking terms govern the purchased services, subject to applicable law.</p><h3>Contact us</h3><p>For questions about these policies or a specific journey, <a href="?page=contact">contact Our Next Boarding</a>.</p></article></section>
